const assert = require('node:assert/strict');
const { isApprovedOfflineReportTask } = require('../src/task-policy.js');

const cases = [
  {
    name: 'approved offline report task is accepted',
    input: {
      directory: 'work/repo',
      files: ['src/report.js'],
      network: 'off',
      sideEffect: 'none'
    },
    expected: true
  },
  {
    name: 'network-enabled task is rejected',
    input: {
      directory: 'work/repo',
      files: ['src/report.js'],
      network: 'on',
      sideEffect: 'none'
    },
    expected: false
  },
  {
    name: 'changed file is rejected',
    input: {
      directory: 'work/repo',
      files: ['src/other.js'],
      network: 'off',
      sideEffect: 'none'
    },
    expected: false
  }
];

let failures = 0;
for (const testCase of cases) {
  try {
    assert.equal(isApprovedOfflineReportTask(testCase.input), testCase.expected);
    console.log('PASS: ' + testCase.name);
  } catch (error) {
    failures += 1;
    console.error('FAIL: ' + testCase.name);
    console.error(error.message);
  }
}

if (failures > 0) {
  console.error(failures + ' test(s) failed.');
  process.exitCode = 1;
} else {
  console.log('3 test(s) passed.');
}

function isApprovedOfflineReportTask(task) {
  return task.directory === 'work/repo'
    && task.files.length === 1
    && task.files[0] === 'src/report.js'
    && task.network === 'off'
    && task.sideEffect === 'none';
}

module.exports = { isApprovedOfflineReportTask };
